configs.config:
// Friday Rifles quit / night: written by CoD2 Unbound. Lines starting with // are comments.
// The name players see in the server list
set sv_hostname "Friday Rifles quit / night"
// How many players can be on the server at once
set sv_maxclients "64"
// Password to join; empty for an open server
set g_password "letmein"
// Admin password, for controlling the server from inside the game; empty turns that off
set rcon_password "adminquit"
// Game type: Team Deathmatch
set g_gametype "tdm"
// Friendly fire: 1 on, 0 off
set scr_friendlyfire "1"
// Players must have the same game files as the server
set sv_pure "1"
// The server doesn’t send files to players
set sv_allowDownload "0"
// Maps, in order
set sv_maprotation "gametype tdm map mp_toujane gametype tdm map mp_burgundy"
// The game’s own log of joins, kills and rounds
set g_log "games_mp.log"
// Start on the first map of the rotation
map_rotate

